object Solution {
    def closeStrings(word1: String, word2: String): Boolean = {
        if (word1.length != word2.length) return false

        val freq1 = word1.groupBy(identity).view.mapValues(_.length).toMap
        val freq2 = word2.groupBy(identity).view.mapValues(_.length).toMap

        // Check if both have the same set of characters
        if (freq1.keySet != freq2.keySet) return false

        // Check if the frequency multisets are the same
        val freqList1 = freq1.values.toList.sorted
        val freqList2 = freq2.values.toList.sorted

        freqList1 == freqList2
    }
}

